/// Registered customer accounts with email/password credentials and profile
/// information. This is an actor table that serves as the primary identity
/// record for customers, storing authentication credentials (email,
/// password_hash) and customer-specific profile data (display_name,
/// phone_number). Each customer can have multiple shipping addresses linked
/// via customer_addresses table and multiple wishlist items via
/// customer_wishlists table.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_customers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Customer's email address for login and communication.
  email String

  /// Encrypted password hash for authentication security.
  password_hash String

  /// Customer's display name shown in public areas.
  display_name String?

  /// Customer's phone number for contact and order notifications.
  phone_number String?

  /// Whether customer has verified their email address.
  email_verified Boolean

  /// Account creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last account update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Account deletion timestamp (soft delete).
  deleted_at DateTime? @db.Timestamptz

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  sessions shopping_mall_customer_sessions[]
  passwordReset shopping_mall_customer_password_resets?
  emailVerifications shopping_mall_customer_email_verifications[]
  sellerProfile shopping_mall_sellers?
  addresses shopping_mall_customer_addresses[]
  shoppingCarts shopping_mall_shopping_carts[]
  wishlists shopping_mall_customer_wishlists[]
  sellerReviews shopping_mall_seller_reviews[]
  cartItems shopping_mall_cart_items[]
  wishlistItems shopping_mall_wishlist_items[]
  orders shopping_mall_orders[]
  cancellationRequests shopping_mall_order_cancellation_requests[]
  refundRequests shopping_mall_order_refund_requests[]
  payments shopping_mall_payments[]
  refundPayments shopping_mall_refund_payments[]
  orderStatusLogs shopping_mall_order_status_logs[]
  reviews shopping_mall_reviews[]
  reviewVotes shopping_mall_review_votes[]

  //----
  // INDEXES
  //----
  @@unique([email])
  @@index([phone_number])
  @@index([created_at])
  @@index([display_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Customer session tracking for JWT authentication with access and refresh
/// tokens
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_customer_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key
  id String @id @db.Uuid

  /// Belonged customer's {@link shopping_mall_customers.id}. Each session
  /// belongs to exactly one customer account.
  shopping_mall_customer_id String @db.Uuid

  /// Unique session identifier
  access_token String

  /// Token used to obtain new access tokens when they expire
  refresh_token String

  /// Timestamp when the session was created
  created_at DateTime @db.Timestamptz

  /// Timestamp when the session will expire
  expired_at DateTime @db.Timestamptz

  /// IP address of the client that created this session
  ip String

  /// Referrer URL of the client that created this session
  referrer String?

  /// Browser user agent string for session tracking
  user_agent String?

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  customer shopping_mall_customers @relation(fields: [shopping_mall_customer_id], references: [id], onDelete: Cascade)

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  refundRequests shopping_mall_order_refund_requests[]

  //----
  // INDEXES
  //----
  @@unique([refresh_token])
  // spellchecker: ignore-next-line
  @@index([shopping_mall_customer_id, created_at], map: "shopping_mall_customer_sessions_shopping_mall_customer_adefa402")
}

/// Password reset tokens for customer account recovery. Each token
/// represents a single password reset request with expiration and usage
/// tracking. Follows security best practices by storing tokens securely and
/// tracking their lifecycle from creation through completion or expiration.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_customer_password_resets {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Customer who requested password reset. {@link shopping_mall_customers.id}.
  shopping_mall_customer_id String @db.Uuid

  /// Hashed password reset token (never store plaintext tokens for security).
  token_hash String

  /// Token expiration timestamp. Password reset links become invalid after
  /// this time.
  expires_at DateTime @db.Timestamptz

  /// Password reset status: pending (active reset), used (token successfully
  /// used), expired (token expired before use), cancelled (reset request
  /// cancelled).
  status String

  /// Timestamp when the password reset token was successfully used to reset
  /// the password.
  used_at DateTime? @db.Timestamptz

  /// Record creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Record last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp. Used for compliance and audit trail preservation.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  // spellchecker: ignore-next-line
  customer shopping_mall_customers @relation(fields: [shopping_mall_customer_id], references: [id], onDelete: Cascade, map: "shopping_mall_customer_password_resets_shopping_mall_c_08961f19")

  //----
  // INDEXES
  //----
  // spellchecker: ignore-next-line
  @@unique([shopping_mall_customer_id], map: "shopping_mall_customer_password_resets_shopping_mall_c_09f142e0")
  @@unique([token_hash])
  // spellchecker: ignore-next-line
  @@index([shopping_mall_customer_id, status], map: "shopping_mall_customer_password_resets_shopping_mall_c_ec36d7a3")
  @@index([expires_at, status])
}

