  /// Administrator's email address for login and communication.
  email String

  /// Encrypted password hash for authentication security.
  password_hash String

  /// Administrator privilege level: regular or super administrator.
  role_grade String

  /// Account creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp. Null means not deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  sessions shopping_mall_admin_sessions[]
  passwordResets shopping_mall_admin_password_resets[]
  migrations shopping_mall_system_migrations[]
  cacheInvalidationLogs shopping_mall_system_cache_trackings[]
  suspensionInitiateds shopping_mall_seller_suspensions[] @relation("shopping_mall_seller_suspensions_of_admin_id")
  suspensionsApproveds shopping_mall_seller_suspensions[] @relation("shopping_mall_seller_suspensions_of_approving_admin_id")
  verifiedSellers shopping_mall_seller_verifications[]
