/// System-wide audit logs capturing all critical operations for compliance
/// and troubleshooting. Records who performed what action, when, from which
/// IP address, and what changes were made. Supports comprehensive audit
/// trail requirements for security, debugging, and regulatory compliance.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_system_audit_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Type of actor who performed the operation (customer, seller, admin,
  /// system).
  actor_type String

  /// ID of the actor who performed the operation (references customer, seller,
  /// admin, or system records).
  actor_id String @db.Uuid

  /// Type of operation performed (create, read, update, delete, login, logout,
  /// approve, reject, suspend, unsuspend).
  operation_type String

  /// Type of entity affected by the operation (customer, seller, product,
  /// order, review, etc.).
  entity_type String

  /// ID of the entity affected by the operation.
  entity_id String @db.Uuid

  /// IP address from which the operation was performed.
  ip_address String

  /// User agent string of the client performing the operation.
  user_agent String?

  /// JSON string containing previous values before the operation (for update
  /// operations).
  old_values String?

  /// JSON string containing new values after the operation.
  new_values String?

  /// Human-readable description of the operation performed.
  description String?

  /// Timestamp when the audit log entry was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the audit log entry was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp for soft delete tracking. Nullable - null means not deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // INDEXES
  //----
  @@index([created_at])
  @@index([actor_id, created_at])
  @@index([operation_type, created_at])
  // spellchecker: ignore-next-line
  @@index([entity_type, entity_id, created_at], map: "shopping_mall_system_audit_logs_entity_type_entity_id__23b08c11")
  // spellchecker: ignore-next-line
  @@index([actor_type, operation_type, created_at], map: "shopping_mall_system_audit_logs_actor_type_operation_t_35ff6598")
}

