/// Main product listings with seller, category, pricing, and deletion status
///
/// @namespace Products
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_products {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Seller who owns this product. {@link shopping_mall_sellers.id}.
  shopping_mall_seller_id String @db.Uuid

  /// Primary category for this product. {@link shopping_mall_categories.id}.
  shopping_mall_category_id String @db.Uuid

  /// Product name displayed to customers.
  name String

  /// Product description with detailed specifications.
  description String

  /// Base price for the product (can be overridden by variant prices).
  base_price Float @db.DoublePrecision

  /// Whether the product is deleted (soft delete).
  is_deleted Boolean

  /// When the product was deleted (null if not deleted).
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  seller   shopping_mall_sellers    @relation(fields: [shopping_mall_seller_id], references: [id], onDelete: Cascade)
  category shopping_mall_categories @relation(fields: [shopping_mall_category_id], references: [id], onDelete: Cascade)

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  wishlists                       shopping_mall_customer_wishlists[]
  productImages                   shopping_mall_product_images[]
  variants                        shopping_mall_product_variants[]
  shoppingMallProductSnapshotsses shopping_mall_product_snapshots[]
  wishlistItems                   shopping_mall_wishlist_items[]
  productSnapshots                shopping_mall_order_product_snapshots[]
  reviews                         shopping_mall_reviews[]

  //----
  // INDEXES
  //----
  @@unique([name])
  @@index([shopping_mall_seller_id])
  @@index([shopping_mall_category_id])
  @@index([is_deleted])
  @@index([base_price])
}

/// Product images with display ordering for product galleries
///
/// @namespace Products
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_product_images {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged product's {@link shopping_mall_products.id}
  shopping_mall_product_id String @db.Uuid

  /// Created by seller's {@link shopping_mall_sellers.id} for audit trail
  shopping_mall_seller_id String @db.Uuid

  /// Image URL for product display
  image_url String @db.VarChar(80000)

  /// Display order for product image galleries (lowest first)
  sort_order Int @db.Integer

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  product         shopping_mall_products @relation(fields: [shopping_mall_product_id], references: [id], onDelete: Cascade)
  createdBySeller shopping_mall_sellers  @relation(fields: [shopping_mall_seller_id], references: [id], onDelete: Cascade)

  // spellchecker: ignore-next-line
  @@unique([shopping_mall_product_id, sort_order], map: "shopping_mall_product_images_shopping_mall_product_id__8f9c6f54")
  //----
  // INDEXES
  //----
  @@index([shopping_mall_seller_id])
}

/// Product variants with SKU codes, pricing overrides, and stock quantities.
/// Each variant represents a specific configuration of options (e.g., 'Red /
/// Large') for its parent product. The option values are stored in a
/// separate child table to ensure 1NF compliance.
///
/// @namespace Products
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_product_variants {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent product this variant belongs to. {@link shopping_mall_products.id}.
  shopping_mall_product_id String @db.Uuid

  /// Unique Stock Keeping Unit code identifying this variant.
  sku_code String

  /// Optional price override specific to this variant. If null, uses product
  /// base price.
  price_override Float? @db.DoublePrecision

  /// Current stock quantity calculated from inventory history records.
  stock_quantity Int @db.Integer

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  product shopping_mall_products @relation(fields: [shopping_mall_product_id], references: [id], onDelete: Cascade)

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  shoppingMallShoppingCartItems shopping_mall_shopping_carts[]
  cartItems                     shopping_mall_cart_items[]
  optionValues                  shopping_mall_product_variant_option_values[]
  inventoryHistories            shopping_mall_inventory_histories[]
  stock                         shopping_mall_variant_stocks?

  //----
  // INDEXES
  //----
  @@unique([sku_code])
  @@index([shopping_mall_product_id])
}

/// Product snapshots capturing complete product state at time of editing for
/// audit and dispute resolution
///
/// @namespace Products
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_product_snapshots {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Original product being snapshotted. {@link shopping_mall_products.id}.
  shopping_mall_product_id String @db.Uuid

  /// Seller who created the product at time of snapshot. {@link
  /// shopping_mall_sellers.id}.
  shopping_mall_seller_id String @db.Uuid

  /// Category at the time of snapshot. {@link shopping_mall_categories.id}.
  shopping_mall_category_id String @db.Uuid

  /// Product name at the time of snapshot.
  name String

  /// Product description at the time of snapshot.
  description String

  /// Base price at the time of snapshot.
  base_price Float @db.DoublePrecision

  /// Product deletion status at the time of snapshot.
  is_deleted Boolean

  /// Deletion timestamp if product was deleted at time of snapshot.
  deleted_at DateTime? @db.Timestamptz

  /// Snapshot creation timestamp for ordering and versioning.
  snapshot_timestamp DateTime @db.Timestamptz

  /// Version number for tracking multiple snapshots of the same product.
  snapshot_version Int @db.Integer

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  originalProduct shopping_mall_products   @relation(fields: [shopping_mall_product_id], references: [id], onDelete: Cascade)
  seller          shopping_mall_sellers    @relation(fields: [shopping_mall_seller_id], references: [id], onDelete: Cascade)
  category        shopping_mall_categories @relation(fields: [shopping_mall_category_id], references: [id], onDelete: Cascade)

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  shoppingMallProductVariantSnapshotsses shopping_mall_product_variant_snapshots[]
  variantSnapshots                       shopping_mall_order_variant_snapshots[]

  // spellchecker: ignore-next-line
  @@unique([shopping_mall_product_id, snapshot_version], map: "shopping_mall_product_snapshots_shopping_mall_product__8c10c02c")
  //----
  // INDEXES
  //----
  @@index([shopping_mall_seller_id])
  @@index([shopping_mall_category_id])
}

/// Product variant snapshots capturing variant details at time of product
