///
/// @namespace Products
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_product_variant_snapshots {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent product snapshot's {@link shopping_mall_product_snapshots.id}.
  product_snapshot_id String @db.Uuid

  /// SKU code of the variant at time of snapshot.
  sku_code String

  /// JSON string containing variant option values (e.g.,
