  //   - format: (propertyKey targetModel)
  //----
  orderItems   shopping_mall_order_items[]
  optionValues shopping_mall_order_variant_snapshot_option_values[]

  //----
  // INDEXES
  //----
  // spellchecker: ignore-next-line
  @@unique([product_snapshot_id, sku_code], map: "shopping_mall_order_variant_snapshots_product_snapshot_d07f7f4c")
  @@index([product_snapshot_id])
}

