      body: {
        name: product.name,
        description: product.description,
        shopping_mall_category_id: product.category.id,
        base_price: product.base_price,
        variants: product.variants.map((v) => ({
          sku_code: v.skuCode,
          option_values: v.optionValues.map((ov) => ({
            option_name: "color",
            option_value: ov,
