export async function test_api_seller_inventory_history_retrieval(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register seller account
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerCredentials = {
    email: typia.assert<string & tags.MinLength<1> & tags.MaxLength<255> & tags.Format<"email">>(
      typia.random<string & tags.Format<"email">>()
    ),
    password: RandomGenerator.alphaNumeric(16),
    shop_name: RandomGenerator.name(),
    shop_description: RandomGenerator.paragraph({ sentences: 2 }),
    logo_image_url: null,
  } satisfies IShoppingMallSeller.IJoin;
  const sellerAuthorized = await authorize_seller_join(sellerConnection, {
    body: sellerCredentials,
  });
  typia.assert(sellerAuthorized);
  // 2. Create product with variant for inventory tracking
  const category = typia.random<IShoppingMallCategory.ISummary>();
  const seller = typia.random<IShoppingMallSeller.ISummary>();
  const productResponse =
    await api.functional.shoppingMall.seller.products.create(sellerConnection, {
      body: {
        name: RandomGenerator.paragraph({ sentences: 1 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        base_price: typia.random<
          number & tags.Type<"uint32"> & tags.MultipleOf<100>
        >(),
        images: [
          {
            image_url: typia.random<string & tags.Format<"uri">>(),
            sort_order: 0,
          },
        ],
        variants: [
          {
            sku_code: `VAR_${RandomGenerator.alphaNumeric(8)}`,
            option_values: [
              {
                option_name: "color",
                option_value: RandomGenerator.pick([
                  "red",
                  "blue",
                  "green",
                  "black",
                ]),
              },
              {
                option_name: "size",
                option_value: RandomGenerator.pick(["S", "M", "L", "XL"]),
              },
            ],
            stock_quantity: 100,
          },
        ],
        shopping_mall_category_id: category.id,
      } satisfies IShoppingMallProduct.ICreate,
    });
  typia.assert(productResponse);
  // 3. Get variant ID from created product
  const variant = productResponse.variants[0];
  if (!variant) {
    throw new Error("No variant created in product");
  }
  // 4. Perform various inventory operations to create history
  // 4.1. Restock inventory with positive quantity
  const restockResponse =
    await api.functional.shoppingMall.seller.inventory.add.addInventory(
      sellerConnection,
      {
        variantId: variant.id,
        body: {
          variant_id: variant.id,
          quantity_change: 50,
          reason: "restock",
          metadata: JSON.stringify({
            source: "supplier_shipment",
            batch: "BATCH_001",
          }),
        } satisfies IShoppingMallInventoryHistory.ICreate,
      },
    );
  typia.assert(restockResponse);
  // 4.2. Deduct inventory through order
  const customerConnection: api.IConnection = { host: connection.host };
  const customerCredentials = {
    email: typia.assert<string & tags.MinLength<1> & tags.MaxLength<255> & tags.Format<"email">>(
      typia.random<string & tags.Format<"email">>()
    ),
    password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    phone_number: RandomGenerator.mobile(),
    href: "https://example.com/register",
    referrer: "https://google.com",
  } satisfies IShoppingMallCustomer.IJoin;
  const customerAuthorized = await authorize_customer_join(customerConnection, {
    body: customerCredentials,
  });
  typia.assert(customerAuthorized);
  // Add variant to cart and checkout to deduct inventory
  const cartResponse =
    await api.functional.shoppingMall.customer.carts.items.create(
      customerConnection,
      {
        body: {
          variant_id: variant.id,
          quantity: 5,
        } satisfies IShoppingMallShoppingCartItem.ICreate,
      },
    );
  typia.assert(cartResponse);
  // 4.3. Manual inventory adjustment
  const adjustResponse =
    await api.functional.shoppingMall.seller.inventory.adjust.adjustInventory(
      sellerConnection,
      {
        body: {
          variant_id: variant.id,
          quantity_change: -10,
          reason: "adjustment",
          metadata: JSON.stringify({
            reason: "stock_count_discrepancy",
            notes: "Physical count lower than system",
          }),
        } satisfies IShoppingMallInventoryHistory.ICreate,
      },
    );
  typia.assert(adjustResponse);
  // 5. Test inventory history retrieval
  const historyResponse =
    await api.functional.shoppingMall.seller.inventory_history.index(
      sellerConnection,
      {
        body: {
          shopping_mall_seller_id: seller.id,
          shopping_mall_product_variant_id: variant.id,
          reason: ["restock", "order", "adjustment"],
          created_at_range: [
            new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString(),
            new Date().toISOString(),
          ],
          page: 1,
          limit: 100,
          sort_by: "created_at",
          sort_order: "desc",
        } satisfies IShoppingMallInventoryHistory.IRequest,
      },
    );
  typia.assert(historyResponse);
  // 6. Validate response structure
  TestValidator.equals(
    "pagination exists",
    historyResponse.pagination !== null,
    true,
  );
  TestValidator.predicate(
    "has data array",
    Array.isArray(historyResponse.data),
  );
  TestValidator.predicate(
    "has at least 3 inventory history records",
    historyResponse.data.length >= 3,
  );
  // 7. Validate individual history records
  for (const record of historyResponse.data) {
    typia.assert<IShoppingMallInventoryHistory.ISummary>(record);
    TestValidator.predicate(
      "has valid reason",
      [
        "order",
        "order_cancellation",
        "refund",
        "restock",
        "adjustment",
        "loss",
      ].includes(record.reason),
    );
    TestValidator.predicate(
      "has valid quantity",
      typeof record.quantity_change === "number",
    );
    TestValidator.predicate(
      "has created timestamp",
      typeof record.created_at === "string",
    );
    // Test filtering capabilities
    if (record.reason === "restock") {
      TestValidator.predicate(
        "restock has positive quantity",
        record.quantity_change > 0,
      );
    } else if (
      record.reason === "order" ||
      record.reason === "adjustment" ||
      record.reason === "loss"
    ) {
      TestValidator.predicate(
        "deduction records have negative or zero quantity",
        record.quantity_change <= 0,
      );
    }
  }
  // 8. Test filtering by specific reason
  const restockOnly =
    await api.functional.shoppingMall.seller.inventory_history.index(
      sellerConnection,
      {
        body: {
          shopping_mall_seller_id: seller.id,
          reason: ["restock"],
          page: 1,
          limit: 10,
        },
      },
    );
  typia.assert(restockOnly);
  TestValidator.predicate(
    "filtered restock only",
    restockOnly.data.every((r) => r.reason === "restock"),
  );
  // 9. Test pagination
  const paginated =
    await api.functional.shoppingMall.seller.inventory_history.index(
      sellerConnection,
      {
        body: {
          shopping_mall_seller_id: seller.id,
          page: 1,
          limit: 2,
        },
      },
    );
  typia.assert(paginated);
  TestValidator.equals(
    "pagination limit respected",
    paginated.data.length <= 2,
    true,
  );
  TestValidator.predicate(
    "pagination metadata correct",
    paginated.pagination.limit === 2,
  );
}

