      TestValidator.equals(
        "order_item has id",
        firstRequest.order_item.id !== null,
        true,
      );
      TestValidator.equals(
        "order_item has quantity",
        firstRequest.order_item.quantity !== null,
        true,
      );
      TestValidator.equals(
