      "auto-confirmed_at is nullable",
      () =>
        firstShipment.autoConfirmedAt === null ||
        firstShipment.autoConfirmedAt === undefined ||
        typeof firstShipment.autoConfirmedAt === "string",
    );
  }
  // Test pagination structure
