  );
  TestValidator.equals(
    "pagination has valid records count",
    shipmentsResponse.pagination.records >= 0,
    true,
  );
  TestValidator.equals(
    "pagination has valid pages count",
    shipmentsResponse.pagination.pages >= 0,
    true,
  );
