    2,
  );
  TestValidator.equals("page 2 has correct limit", page2.pagination.limit, 5);
  // Test 6: Pagination - large limit (100)
  const largeLimit =
    await api.functional.shoppingMall.seller.sellers.products.variants.index(
      sellerConnection,
