          >(),
          images: [],
          variants: [
            {
              sku_code: `SKU-${RandomGenerator.alphabets(6).toUpperCase()}`,
              option_values: [
                { option_name: "color", option_value: "red" },
                { option_name: "size", option_value: "M" },
