              sku_code: `SKU-${RandomGenerator.alphabets(6).toUpperCase()}`,
              option_values: [
                { option_name: "color", option_value: "blue" },
                { option_name: "size", option_value: "L" },
              ],
              stock_quantity: 50,
            },
          ],
        } satisfies IShoppingMallProduct.ICreate,
      },
