  // Test with rejected approval status filter
  const rejectedFilter: IShoppingMallSeller.IRequest = {
    page: 1,
    limit: 10,
    approval_status: "rejected",
  };
  const rejectedResult =
    await api.functional.shoppingMall.admin.admin.sellers.index(
      adminConnection,
      { body: rejectedFilter },
    );
