import { authorize_seller_join } from "../../../authorize/authorize_seller_join";
import { authorize_seller_login } from "../../../authorize/authorize_seller_login";
import { authorize_seller_refresh } from "../../../authorize/authorize_seller_refresh";

export async function test_api_seller_inventory_history_pagination(
  connection: api.IConnection,
): Promise<void> {
  // Seller authentication
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerCredentials = {
    email: "seller_test@example.com",
    password: "TestPassword123!",
    shop_name: "Test Seller Shop",
    shop_description: "A test shop for inventory history pagination",
    logo_image_url: null,
  } satisfies IShoppingMallSeller.IJoin;
  // Register and authenticate seller
  const sellerAuth = await authorize_seller_join(sellerConnection, {
    body: sellerCredentials,
  });
  typia.assert(sellerAuth);
  // Create seller-specific connection with authentication token from result
  const sellerConnWithToken: api.IConnection = {
    host: connection.host,
    headers: { Authorization: `Bearer ${sellerAuth.token.access}` },
  };
  // Test pagination with various parameters
  const testPages = async () => {
    // Request first page with limit of 2
    const firstPage =
      await api.functional.shoppingMall.seller.inventory_histories.index(
        sellerConnWithToken,
        {
          body: {
            page: 1,
            limit: 2,
            sort_by: "created_at",
            sort_order: "desc",
          } satisfies IShoppingMallInventoryHistory.IRequest,
        },
      );
    typia.assert(firstPage);
    // Validate pagination metadata
    TestValidator.equals("first page current", firstPage.pagination.current, 1);
    TestValidator.equals("first page limit", firstPage.pagination.limit, 2);
    TestValidator.predicate("first page has data", firstPage.data.length >= 0);
    if (firstPage.data.length > 0) {
      // Verify newest first ordering
      for (let i = 0; i < firstPage.data.length - 1; i++) {
        TestValidator.predicate(
          `ordering check ${i}: ${firstPage.data[i].created_at} >= ${firstPage.data[i + 1].created_at}`,
          new Date(firstPage.data[i].created_at) >=
            new Date(firstPage.data[i + 1].created_at),
        );
      }
    }
    // Request second page
    const secondPage =
      await api.functional.shoppingMall.seller.inventory_histories.index(
        sellerConnWithToken,
        {
          body: {
            page: 2,
            limit: 2,
            sort_by: "created_at",
            sort_order: "desc",
          } satisfies IShoppingMallInventoryHistory.IRequest,
        },
      );
    typia.assert(secondPage);
    // Validate second page metadata
    TestValidator.equals(
      "second page current",
      secondPage.pagination.current,
      2,
    );
    TestValidator.equals("second page limit", secondPage.pagination.limit, 2);
    // Request page beyond available data
    const emptyPage =
      await api.functional.shoppingMall.seller.inventory_histories.index(
        sellerConnWithToken,
        {
          body: {
            page: 999,
            limit: 2,
          } satisfies IShoppingMallInventoryHistory.IRequest,
        },
      );
    typia.assert(emptyPage);
    TestValidator.equals(
      "empty page current",
      emptyPage.pagination.current,
      999,
    );
    TestValidator.equals("empty page data length", emptyPage.data.length, 0);
  };
  await testPages();
  // Test filtering by seller ID (should include self)
  const filteredPage =
    await api.functional.shoppingMall.seller.inventory_histories.index(
      sellerConnWithToken,
      {
        body: {
          page: 1,
          limit: 10,
          shopping_mall_seller_id: sellerAuth.data.profile.id,
        } satisfies IShoppingMallInventoryHistory.IRequest,
      },
    );
  typia.assert(filteredPage);
  // Test with no filters (default behavior)
  const defaultPage =
    await api.functional.shoppingMall.seller.inventory_histories.index(
      sellerConnWithToken,
      {
        body: {
          page: 1,
          limit: 20,
        } satisfies IShoppingMallInventoryHistory.IRequest,
      },
    );
  typia.assert(defaultPage);
  TestValidator.equals(
    "default page current",
    defaultPage.pagination.current,
    1,
  );
  TestValidator.predicate(
    "default page has pagination",
    defaultPage.pagination.records >= 0,
  );
}

