import { MyGlobal } from "../MyGlobal";
import { AdminPayload } from "../decorators/payload/AdminPayload";
import { ShoppingMallOrderTransformer } from "../transformers/ShoppingMallOrderTransformer";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postShoppingMallAdminOrdersOrderIdForceActionsRefund(props: {
  admin: AdminPayload;
  orderId: string;
  body: IShoppingMallOrder.IRequest;
}): Promise<IShoppingMallOrder> {
  // Verify the order exists
  const order = await MyGlobal.prisma.shopping_mall_orders.findFirstOrThrow({
    where: {
      id: props.orderId,
    },
    ...ShoppingMallOrderTransformer.select(),
  });
  // Validate order status for refund (must be paid, shipped, or delivered)
  if (!["paid", "shipped", "delivered"].includes(order.status)) {
    throw new HttpException(
      `Order cannot be refunded with current status: ${order.status}`,
      400,
    );
  }
  // Get all order items
  const orderItems = order.orderItems;
  // Update each order item to 'refunded' status
  const now = new Date();
  const nowISOString = toISOStringSafe(now);
  // Update inventory for each order item
  for (const item of orderItems) {
    // Restore inventory quantity
    await MyGlobal.prisma.shopping_mall_inventory_histories.create({
      data: {
        id: v4(),
        shopping_mall_product_variant_id: item.variantSnapshot.id,
        quantity_change: item.quantity,
        reason: "administrator refund",
        shopping_mall_order_item_id: item.id,
        created_at: nowISOString,
      },
    });
    // Update order item status to 'refunded'
    await MyGlobal.prisma.shopping_mall_order_items.update({
      where: {
        id: item.id,
      },
      data: {
        item_status: "refunded" as const,
      },
    });
    // Create refund request first
    const refundRequest =
      await MyGlobal.prisma.shopping_mall_order_refund_requests.create({
        data: {
          id: v4(),
          shopping_mall_order_item_id: item.id,
          shopping_mall_customer_id: order.shopping_mall_customer_id,
          shopping_mall_seller_id: item.sellerProfileSnapshot.id,
          shopping_mall_customer_session_id: v4(),
          reason: "Administrator force refund",
          created_at: nowISOString,
          status: "approved",
          approved_at: nowISOString,
        },
      });
    // Create refund payment record with correct fields
    await MyGlobal.prisma.shopping_mall_refund_payments.create({
      data: {
        id: v4(),
        refund_request_id: refundRequest.id,
        order_item_id: item.id,
        customer_id: order.shopping_mall_customer_id,
        seller_id: item.sellerProfileSnapshot.id,
        transaction_id: v4(),
        refund_amount: item.total_price,
        currency: "KRW",
        refund_reason: "Administrator force refund",
        status: "completed",
        processed_at: nowISOString,
        reconciled: false,
      },
    });
  }
  // Update order status to 'refunded' if all items are now refunded
  const updatedOrderItems =
    await MyGlobal.prisma.shopping_mall_order_items.findMany({
      where: {
        shopping_mall_order_id: props.orderId,
      },
      select: {
        item_status: true,
      },
    });
  const allRefunded = updatedOrderItems.every(
    (item) => item.item_status === "refunded",
  );
  if (allRefunded) {
    await MyGlobal.prisma.shopping_mall_orders.update({
      where: {
        id: props.orderId,
      },
      data: {
        status: "refunded" as const,
      },
    });
    // Log the administrator action
    await MyGlobal.prisma.shopping_mall_order_status_logs.create({
      data: {
        id: v4(),
        shopping_mall_order_id: props.orderId,
        previous_status: order.status,
        new_status: "refunded",
        reason: `Administrator refund requested: ${"reason" in props.body ? props.body.reason : "No reason provided"}`,
        created_at: nowISOString,
        changed_by: props.admin.id,
      },
    });
  }
  // Get updated order with all changes
  const updatedOrder =
    await MyGlobal.prisma.shopping_mall_orders.findUniqueOrThrow({
      where: {
        id: props.orderId,
      },
      ...ShoppingMallOrderTransformer.select(),
    });
  return await ShoppingMallOrderTransformer.transform(updatedOrder);
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IShoppingMallOrderCancellationRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderCancellationRequest";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { SellerPayload } from "../decorators/payload/SellerPayload";
import { ShoppingMallOrderCancellationRequestTransformer } from "../transformers/ShoppingMallOrderCancellationRequestTransformer";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function putShoppingMallSellerCancellationRequestsRequestIdApprove(props: {
  seller: SellerPayload;
  requestId: string;
}): Promise<IShoppingMallOrderCancellationRequest> {
  // Step 1: Retrieve cancellation request with full relations
  const request =
    await MyGlobal.prisma.shopping_mall_order_cancellation_requests.findUniqueOrThrow(
      {
        where: { id: props.requestId },
        select: {
          id: true,
          order_item_id: true,
          customer_id: true,
          reason: true,
          status: true,
          rejection_reason: true,
          responded_by: true,
          created_at: true,
          responded_at: true,
          orderItem: {
            select: {
              id: true,
              quantity: true,
              shopping_mall_order_variant_snapshot_id: true,
              shopping_mall_order_seller_profile_snapshot_id: true,
            },
          },
        },
      },
    );
  // Step 2: Validate request status is "pending"
  if (request.status !== "pending") {
    throw new HttpException("Cancellation request is not pending", 400);
  }
  // Step 3: Verify seller owns the product through order item
  const orderItem = request.orderItem;
  if (!orderItem) {
    throw new HttpException("Order item not found", 404);
  }
  const sellerProfileSnapshot =
    await MyGlobal.prisma.shopping_mall_order_seller_profile_snapshots.findUniqueOrThrow(
      {
        where: { id: orderItem.shopping_mall_order_seller_profile_snapshot_id },
        select: {
          id: true,
        },
      },
    );
  if (sellerProfileSnapshot.id !== props.seller.id) {
    throw new HttpException("Forbidden: You do not own this product", 403);
  }
  // Step 4: Create cancellation request log
  await MyGlobal.prisma.shopping_mall_order_cancellation_request_logs.create({
    data: {
      id: v4(),
      shopping_mall_order_cancellation_request_id: props.requestId,
      responded_by: props.seller.id,
      from_status: "pending",
      to_status: "approved",
      created_at: toISOStringSafe(new Date()),
    },
  });
  // Step 5: Update cancellation request status
  const updatedRequest =
    await MyGlobal.prisma.shopping_mall_order_cancellation_requests.update({
      where: { id: props.requestId },
      data: {
        status: "approved",
        responded_by: props.seller.id,
        responded_at: toISOStringSafe(new Date()),
      },
      select: {
        id: true,
        order_item_id: true,
        customer_id: true,
        reason: true,
        status: true,
        rejection_reason: true,
        responded_by: true,
        created_at: true,
        responded_at: true,
        orderItem: {
          select: {
            id: true,
            quantity: true,
            shopping_mall_order_variant_snapshot_id: true,
          },
        },
      },
    });
  // Step 6: Restore stock quantity for the variant
  const variantSnapshot =
    await MyGlobal.prisma.shopping_mall_order_variant_snapshots.findUniqueOrThrow(
      {
        where: {
          id: updatedRequest.orderItem.shopping_mall_order_variant_snapshot_id,
        },
        select: {
          id: true,
          shopping_mall_product_variant_id: true,
        },
      },
    );
  await MyGlobal.prisma.shopping_mall_inventory_histories.create({
    data: {
      id: v4(),
      shopping_mall_product_variant_id:
        variantSnapshot.shopping_mall_product_variant_id,
      shopping_mall_order_item_id: updatedRequest.order_item_id,
      quantity_change: updatedRequest.orderItem.quantity,
      reason: "order_cancellation",
      created_at: toISOStringSafe(new Date()),
    },
  });
  // Step 7: Update order item status to cancelled
  await MyGlobal.prisma.shopping_mall_order_items.update({
    where: { id: updatedRequest.order_item_id },
    data: {
      item_status: "cancelled",
    },
  });
  // Step 8: Create refund request
  await MyGlobal.prisma.shopping_mall_order_refund_requests.create({
    data: {
      id: v4(),
      shopping_mall_order_item_id: updatedRequest.order_item_id,
      customer_id: updatedRequest.customer_id,
      seller_id: props.seller.id,
      customer_session_id: v4(),
      created_at: toISOStringSafe(new Date()),
      updated_at: toISOStringSafe(new Date()),
      reason: "Cancellation approved by seller",
      status: "approved",
    },
  });
  // Step 9: Return the updated cancellation request with full details
  return await ShoppingMallOrderCancellationRequestTransformer.transform(
    await MyGlobal.prisma.shopping_mall_order_cancellation_requests.findUniqueOrThrow(
      {
        where: { id: props.requestId },
        ...ShoppingMallOrderCancellationRequestTransformer.select(),
      },
    ),
  );
}

