export async function putShoppingMallAdminAdministratorsAdminIdPromote(props: {
  admin: AdminPayload;
  adminId: string;
  body: IShoppingMallAdmin.IPromote;
}): Promise<IShoppingMallAdmin> {
  const admin = await MyGlobal.prisma.shopping_mall_admins.findUniqueOrThrow({
    where: { id: props.adminId },
  });
  if (admin.role_grade !== "regular") {
    throw new HttpException(
      "Administrator must have regular grade to be promoted",
      400,
    );
  }
  if (admin.id === props.admin.id) {
    throw new HttpException(
      "Super administrators cannot promote themselves",
      400,
    );
  }
  const updated = await MyGlobal.prisma.shopping_mall_admins.update({
    where: { id: props.adminId },
    data: {
      role_grade: "super",
      updated_at: new Date().toISOString(),
    },
    select: {
      id: true,
      email: true,
      role_grade: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
    },
  });
  await MyGlobal.prisma.shopping_mall_system_audit_logs.create({
    data: {
      id: v4(),
      actor_id: props.admin.id,
      actor_type: "admin",
      operation_type: "promote",
      entity_type: "admin",
      entity_id: props.adminId,
      ip_address: "127.0.0.1",
      user_agent: "System",
      description: `Promoted administrator ${props.adminId} to super grade: ${props.body.reason}`,
      new_values: JSON.stringify({ role_grade: "super" }),
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    },
  });
  return {
    id: updated.id,
    reason: props.body.reason,
    status: "approved",
    created_at: updated.created_at.toISOString(),
    approved_at: updated.updated_at.toISOString(),
    rejected_at: null,
    rejection_reason: null,
    requester: {
      id: props.admin.id,
      email: props.admin.id as string,
      created_at: updated.created_at.toISOString(),
      updated_at: updated.updated_at.toISOString(),
      display_name: null,
      phone_number: null,
      email_verified: false,
    } satisfies IShoppingMallCustomer.ISummary,
  };
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function getShoppingMallCategoriesHierarchy(): Promise<IShoppingMallCategory.IInvert> {
  // Query all categories to build complete hierarchy
  const allCategories = await MyGlobal.prisma.shopping_mall_categories.findMany(
    {
      where: { deleted_at: null },
      orderBy: [{ parent_category_id: "asc" }, { name: "asc" }],
      select: {
        id: true,
        name: true,
        description: true,
        parent_category_id: true,
        created_at: true,
        updated_at: true,
        deleted_at: true,
      },
    },
  );
  // Build category map with children arrays
  const categoryMap = new Map<
    string,
    {
      data: (typeof allCategories)[0];
      children: (typeof allCategories)[0][];
    }
  >();
  // Initialize all categories in map
  for (const category of allCategories) {
    categoryMap.set(category.id, {
      data: category,
      children: [],
    });
  }
  // Build parent-child relationships
  for (const category of allCategories) {
    if (category.parent_category_id !== null) {
      const parent = categoryMap.get(category.parent_category_id);
      if (parent) {
        parent.children.push(category);
      }
    }
  }
  // Get root categories (those with no parent)
  const rootCategories = allCategories.filter(
    (c) => c.parent_category_id === null,
  );
  // Transform to IInvert format
  const children = await ArrayUtil.asyncMap(
    rootCategories,
    async (category) => {
      const categoryData = categoryMap.get(category.id)!.data;
      const childrenList = categoryMap.get(category.id)!.children;
      return {
        id: categoryData.id,
        name: categoryData.name,
        description: categoryData.description ?? null,
        parent_category_id: categoryData.parent_category_id ?? null,
        created_at: categoryData.created_at.toISOString(),
        updated_at: categoryData.updated_at.toISOString(),
        deleted_at: categoryData.deleted_at?.toISOString() ?? null,
        children: await ArrayUtil.asyncMap(childrenList, (child) => {
          return {
            id: child.id,
            name: child.name,
            description: child.description ?? null,
            parent: {
              id: categoryData.id,
              name: categoryData.name,
              description: categoryData.description ?? null,
              parent: null,
              subcategory_count: 0,
            } satisfies IShoppingMallCategory.ISummary,
            subcategory_count: 0,
          } satisfies IShoppingMallCategory.ISummary;
        }),
      } satisfies IShoppingMallCategory.IInvert;
    },
  );
  // Return first category if single root, or construct combined structure
  if (children.length === 0) {
    return {
      id: v4(),
      name: "Categories",
      description: null,
      parent_category_id: null,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
      deleted_at: null,
      children: [],
    };
  } else if (children.length === 1) {
    return children[0];
  } else {
    return {
      id: v4(),
      name: "Categories",
      description: null,
      parent_category_id: null,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
      deleted_at: null,
      children: children,
    };
  }
}

