import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { SellerPayload } from "../decorators/payload/SellerPayload"

export async function postShoppingMallSellerSellersProducts(props: {
    seller: SellerPayload;
    body: IShoppingMallProduct.ICreate;
}): Promise<IShoppingMallProduct> {
    // First, verify the category exists and belongs to the seller
    const category = await MyGlobal.prisma.shopping_mall_categories.findFirst({
        where: {
            id: props.body.shopping_mall_category_id,
        },
    });
    if (!category) {
        throw new HttpException("Category not found", 404);
    }
    const created = await MyGlobal.prisma.shopping_mall_products.create({
        data: {
            id: v4(),
            name: props.body.name,
            description: props.body.description,
            base_price: props.body.base_price,
            is_deleted: false,
            deleted_at: null,
            // Connect seller relation
            seller: { connect: { id: props.seller.id } },
            // Connect category relation
            category: { connect: { id: props.body.shopping_mall_category_id } },
            // Create product images with proper relation
            productImages: props.body.images
                ? {
                    create: await ArrayUtil.asyncMap(props.body.images, (image) => ({
                        id: v4(),
                        image_url: image.image_url,
                        sort_order: image.sort_order,
                    })),
                }
                : undefined,
            // Create variants with proper relation
            variants: {
                create: await ArrayUtil.asyncMap(props.body.variants, (variant) => ({
                    id: v4(),
                    sku_code: variant.sku_code,
                    stock_quantity: variant.stock_quantity ?? 0,
                    price_override: variant.price_override ?? null,
                    // Connect product relation
                    product: { connect: { id: v4() } },
                    // Create option values
                    productVariantOptionValues: {
                        create: await ArrayUtil.asyncMap(variant.option_values, (opt) => ({
                            id: v4(),
                            option_name: opt.option_name,
                            option_value: opt.option_value,
                        })),
                    },
                })),
            },
        },
        include: {
            seller: true,
            category: true,
            productImages: true,
            variants: {
                include: {
                    productVariantOptionValues: true,
                    product: {
                        include: {
                            seller: true,
                            category: true,
                        }
                    }
                }
            },
        },
    });
    // Build the response with proper data structure
    return {
        id: created.id,
        name: created.name,
        description: created.description,
        base_price: Number(created.base_price),
        is_deleted: created.is_deleted,
        category: {
            id: created.category.id,
            name: created.category.name,
            description: created.category.description,
            parent: created.category.parent_category_id
                ? {
                    id: created.category.parent.id,
                    name: created.category.parent.name,
                    description: created.category.parent.description,
                    parent: null,
                    subcategory_count: 0,
                }
                : null,
        },
        seller: {
            id: created.seller.id,
            shop_name: created.seller.shop_name,
            approval_status: created.seller.approval_status,
            created_at: created.seller.created_at.toISOString(),
        },
        images: created.productImages.map((img) => ({
            id: img.id,
            image_url: img.image_url,
            sort_order: img.sort_order,
        })),
        variants: created.variants.map((v) => ({
            id: v.id,
            shoppingMallProductId: v.shopping_mall_product_id,
            skuCode: v.sku_code,
            priceOverride: v.price_override,
            stockQuantity: v.stock_quantity,
            optionValues: v.productVariantOptionValues.map((ov) => ov.option_value),
            product: {
                id: v.product.id,
                name: v.product.name,
                description: v.product.description,
                base_price: Number(v.product.base_price),
                is_deleted: v.product.is_deleted,
                seller: {
                    id: v.product.seller.id,
                    shop_name: v.product.seller.shop_name,
                    approval_status: v.product.seller.approval_status,
                    created_at: v.product.seller.created_at.toISOString(),
                },
                category: {
                    id: v.product.category.id,
                    name: v.product.category.name,
                    description: v.product.category.description,
                    parent: v.product.category.parent_category_id
                        ? {
                            id: v.product.category.parent.id,
                            name: v.product.category.parent.name,
                            description: v.product.category.parent.description,
                            parent: null,
                            subcategory_count: 0,
                        }
                        : null,
                },
                average_rating: 0,
            },
        })),
    };
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IShoppingMallCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCartItem";
import { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import { IShoppingMallProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductVariant";
import { IShoppingMallProductVariantOptionValue } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductVariantOptionValue";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function putShoppingMallCustomerCartItemsCartItemId(props: {
  customer: CustomerPayload;
  cartItemId: string & tags.Format<"uuid">;
  body: IShoppingMallCartItem.IUpdate;
}): Promise<IShoppingMallCartItem> {
  // Load the cart item with variant and product information
  const cartItem =
    await MyGlobal.prisma.shopping_mall_cart_items.findFirstOrThrow({
      where: {
        id: props.cartItemId,
        customer_id: props.customer.id,
      },
      select: {
        id: true,
        quantity: true,
        added_at: true,
        customer_id: true,
        variant_id: true,
        variant: {
          select: {
            id: true,
            sku_code: true,
            price_override: true,
            stock_quantity: true,
            shopping_mall_product_id: true,
            shoppingMallProductVariantOptionValues: {
              select: {
                option_name: true,
                option_value: true,
              },
            } satisfies Prisma.shopping_mall_product_variant_option_valuesFindManyArgs,
            product: {
              select: {
                id: true,
                name: true,
                base_price: true,
                is_deleted: true,
                seller: {
                  select: {
                    id: true,
                    shop_name: true,
                    approval_status: true,
                    created_at: true,
                  },
                },
                category: {
                  select: {
                    id: true,
                    name: true,
                    description: true,
                    parent_category_id: true,
                  },
                },
                reviews: {
                  select: {
                    rating: true,
                    deleted_at: true,
                  },
                },
              },
            },
          },
        },
      },
    });
  // Validate quantity
  const quantity = props.body.quantity;
  if (quantity < 1) {
    throw new HttpException("Quantity must be at least 1", 400);
  }
  // Check stock availability
  if (cartItem.variant.stock_quantity < quantity) {
    throw new HttpException(
      `Insufficient stock. Available: ${cartItem.variant.stock_quantity}, Requested: ${quantity}`,
      400,
    );
  }
  // Check if product is deleted
  if (cartItem.variant.product.is_deleted) {
    throw new HttpException("Product is no longer available", 404);
  }
  // Update the cart item quantity
  const updated = await MyGlobal.prisma.shopping_mall_cart_items.update({
    where: { id: props.cartItemId },
    data: { quantity },
    select: {
      id: true,
      quantity: true,
      added_at: true,
      customer_id: true,
      variant_id: true,
      variant: {
        select: {
          id: true,
          sku_code: true,
          price_override: true,
          stock_quantity: true,
          shopping_mall_product_id: true,
          shoppingMallProductVariantOptionValues: {
            select: {
              option_name: true,
              option_value: true,
            },
          } satisfies Prisma.shopping_mall_product_variant_option_valuesFindManyArgs,
          product: {
            select: {
              id: true,
              name: true,
              base_price: true,
              is_deleted: true,
              seller: {
                select: {
                  id: true,
                  shop_name: true,
                  approval_status: true,
                  created_at: true,
                },
              },
            },
          },
        },
      },
    },
  });
  // Build response using loaded data and transformer
  const nonDeletedReviews = updated.variant.product.reviews.filter(
    (r) => r.deleted_at === null,
  );
  const avgRating =
    nonDeletedReviews.length > 0
      ? Math.round(
          nonDeletedReviews.reduce((sum, r) => sum + r.rating, 0) /
            nonDeletedReviews.length,
        )
      : 0;
  return {
    id: updated.id,
    quantity: updated.quantity,
    added_at: updated.added_at.toISOString(),
    customer_id: updated.customer_id,
    variant_id: updated.variant_id,
    customer: {
      id: updated.customer_id,
      email: "" as string & tags.Format<"email">,
      display_name: null,
      phone_number: null,
      email_verified: false,
      created_at: "" as string & tags.Format<"date-time">,
      updated_at: "" as string & tags.Format<"date-time">,
    } satisfies IShoppingMallCustomer.ISummary,
    variant: {
      id: updated.variant.id,
      sku_code: updated.variant.sku_code,
      price_override: updated.variant.price_override ?? null,
      stock_quantity: updated.variant.stock_quantity,
      shopping_mall_product_id: updated.variant.product.id,
      shoppingMallProductVariantOptionValues:
        updated.variant.shoppingMallProductVariantOptionValues,
      product: {
        id: updated.variant.product.id,
        name: updated.variant.product.name,
        base_price: updated.variant.product.base_price,
        is_deleted: updated.variant.product.is_deleted,
        seller: {
          id: updated.variant.product.seller.id,
          shop_name: updated.variant.product.seller.shop_name,
          approval_status: updated.variant.product.seller.approval_status,
          created_at: updated.variant.product.seller.created_at.toISOString(),
        } satisfies IShoppingMallSeller.ISummary,
        category: {
          id: updated.variant.product.category.id,
          name: updated.variant.product.category.name,
          description: updated.variant.product.category.description ?? null,
          parent: updated.variant.product.category.parent_category_id
            ? {
                id: updated.variant.product.category.parent_category_id,
                name: "",
                description: null,
                parent: null,
                subcategory_count: 0,
              }
            : null,
          subcategory_count: 0,
        } satisfies IShoppingMallCategory.ISummary,
        average_rating: avgRating,
      } satisfies IShoppingMallProduct.ISummary,
    } satisfies IShoppingMallProductVariant.ISummary,
  } satisfies IShoppingMallCartItem;
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { AdminPayload } from "../decorators/payload/AdminPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function deleteShoppingMallAdminCategoriesCategoryId(props: {
  admin: AdminPayload;
  categoryId: string;
}): Promise<void> {
  // Step 1: Verify category exists and has no subcategories
  const category = await MyGlobal.prisma.shopping_mall_categories.findUnique({
    where: { id: props.categoryId },
  });
  if (category === null) {
    throw new HttpException("Category not found", 404);
  }
  const subcategoryCount = await MyGlobal.prisma.shopping_mall_categories.count(
    {
      where: { parent_category_id: props.categoryId },
    },
  );
  if (subcategoryCount > 0) {
    throw new HttpException(
      "Category has subcategories. Delete subcategories first.",
      409,
    );
  }
  // Step 2: Move all products in this category to uncategorized
  // Using Prisma's set operation to remove category association
  await MyGlobal.prisma.shopping_mall_products.updateMany({
    where: { shopping_mall_category_id: props.categoryId },
    data: {
      shopping_mall_category: {
        disconnect: true,
      },
    },
  });
  // Step 3: Create category snapshot preserving name and description
  await MyGlobal.prisma.shopping_mall_product_snapshots.create({
    data: {
      id: v4(),
      shopping_mall_product_id: v4(),
      shopping_mall_seller_id: v4(),
      shopping_mall_category_id: category.id,
      name: category.name,
      description: category.description ?? "",
      base_price: 0,
      is_deleted: false,
      snapshot_timestamp: new Date().toISOString(),
      snapshot_version: 1,
    },
  });
  // Step 4: Soft delete the category
  await MyGlobal.prisma.shopping_mall_categories.update({
    where: { id: props.categoryId },
    data: {
      deleted_at: new Date().toISOString(),
    },
  });
  // Step 5: Log deletion event to system audit log
  await MyGlobal.prisma.shopping_mall_system_audit_logs.create({
    data: {
      id: v4(),
      actor_type: "admin",
      actor_id: props.admin.id,
      operation_type: "category_delete",
      entity_type: "category",
      entity_id: props.categoryId,
      ip_address: "0.0.0.0",
      user_agent: null,
      old_values: null,
      new_values: null,
      description: null,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    },
  });
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { SellerPayload } from "../decorators/payload/SellerPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function deleteShoppingMallSellerProductsProductId(props: {
  seller: SellerPayload;
  productId: string;
}): Promise<void> {
  // Verify the product exists and belongs to the seller
  const product = await MyGlobal.prisma.shopping_mall_products.findFirst({
    where: {
      id: props.productId,
      shopping_mall_seller_id: props.seller.id,
      deleted_at: null,
    },
  });
  if (!product) {
    throw new HttpException("Product not found", 404);
  }
  // Get all variant IDs first
  const variants =
    await MyGlobal.prisma.shopping_mall_product_variants.findMany({
      where: {
        shopping_mall_product_id: props.productId,
      },
      select: {
        id: true,
      },
    });
  const variantIds = variants.map((v) => v.id);
  // Get all variant snapshot IDs
  const variantSnapshots =
    await MyGlobal.prisma.shopping_mall_product_variant_snapshots.findMany({
      where: {
        shopping_mall_product_variant_id: {
          in: variantIds,
        },
      },
      select: {
        id: true,
      },
    });
  const variantSnapshotIds = variantSnapshots.map((v) => v.id);
  // Check if product has pending order items (paid or shipped status)
  const hasPendingOrders =
    await MyGlobal.prisma.shopping_mall_order_items.findFirst({
      where: {
        shopping_mall_product_variant_id: {
          in: variantIds,
        },
        status: {
          in: ["paid", "shipped"],
        },
      },
    });
  if (hasPendingOrders) {
    throw new HttpException(
      "Product has pending orders and cannot be deleted",
      400,
    );
  }
  // Check if product has pending cancellation requests
  const hasPendingCancellation =
    await MyGlobal.prisma.shopping_mall_order_cancellation_requests.findFirst({
      where: {
        order_item_id: {
          in: await MyGlobal.prisma.shopping_mall_order_items
            .findMany({
              where: {
                shopping_mall_product_variant_id: {
                  in: variantIds,
                },
              },
              select: {
                id: true,
              },
            })
            .then((items) => items.map((i) => i.id)),
        },
      },
      status: "pending",
    });
}
if (hasPendingCancellation) {
  throw new HttpException("Product has pending cancellation requests", 400);
}
// Check if product has pending refund requests
const hasPendingRefund =
  await MyGlobal.prisma.shopping_mall_order_refund_requests.findFirst({
    where: {
      shopping_mall_order_item_id: {
        in: await MyGlobal.prisma.shopping_mall_order_items
          .findMany({
            where: {
              shopping_mall_product_variant_id: {
                in: variantIds,
              },
            },
            select: {
              id: true,
            },
          })
          .then((items) => items.map((i) => i.id)),
      },
    },
    status: "pending",
  });
if (hasPendingRefund) {
  throw new HttpException("Product has pending refund requests", 400);
}
// Delete product images
await MyGlobal.prisma.shopping_mall_product_images.deleteMany({
  where: {
    shopping_mall_product_id: props.productId,
  },
});
// Delete inventory records
await MyGlobal.prisma.shopping_mall_inventory_histories.deleteMany({
  where: {
    shopping_mall_product_variant_id: {
      in: variantIds,
    },
  },
});
// Delete variant option values
await MyGlobal.prisma.shopping_mall_product_variant_option_values.deleteMany({
  where: {
    shopping_mall_product_variant_id: {
      in: variantIds,
    },
  },
});
// Delete variant snapshots
await MyGlobal.prisma.shopping_mall_product_variant_snapshots.deleteMany({
  where: {
    id: {
      in: variantSnapshotIds,
    },
  },
});
// Delete variants
await MyGlobal.prisma.shopping_mall_product_variants.deleteMany({
  where: {
    shopping_mall_product_id: props.productId,
  },
});
// Delete from customer wishlists
