export async function patchShoppingMallSellers(props: {
  body: IShoppingMallSeller.IRequest;
}): Promise<IPageIShoppingMallSeller.ISummary> {
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 100;
  const skip = (page - 1) * limit;
  const where: Prisma.shopping_mall_sellersWhereInput = {
    ...(props.body.search && {
      shop_name: { contains: props.body.search, mode: "insensitive" },
    }),
    ...(props.body.approval_status && {
      approval_status: props.body.approval_status,
    }),
  } satisfies Prisma.shopping_mall_sellersWhereInput;
  const orderByInput = (
    props.body.sort === "shop_name:asc"
      ? { shop_name: "asc" as const }
      : props.body.sort === "created_at:asc"
        ? { created_at: "asc" as const }
        : { created_at: "desc" as const }
  ) satisfies Prisma.shopping_mall_sellersOrderByWithRelationInput;
  const data = await MyGlobal.prisma.shopping_mall_sellers.findMany({
    where,
    orderBy: orderByInput,
    skip,
    take: limit,
    select: {
      id: true,
      shop_name: true,
      approval_status: true,
      created_at: true,
    },
  });
  const total = await MyGlobal.prisma.shopping_mall_sellers.count({ where });
  return {
    data: data.map((seller) => ({
      id: seller.id as string & tags.Format<"uuid">,
      shop_name: seller.shop_name,
      approval_status: seller.approval_status,
      created_at: toISOStringSafe(seller.created_at),
    })),
    pagination: {
      current: (page - 1 < 0 ? 0 : page) satisfies number as number &
        tags.Type<"int32"> &
        tags.Minimum<0>,
      limit: limit satisfies number as number &
        tags.Type<"int32"> &
        tags.Minimum<0>,
      records: total satisfies number as number &
        tags.Type<"int32"> &
        tags.Minimum<0>,
      pages: Math.ceil(total / limit) satisfies number as number &
        tags.Type<"int32"> &
        tags.Minimum<0>,
    } satisfies IPage.IPagination,
  };
}

import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IShoppingMallAdminSessions } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdminSessions";
import { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { ShoppingMallCustomerTransformer } from "../transformers/ShoppingMallCustomerTransformer";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postShoppingMallAuthCustomerLogin(props: {
  ip: string;
  body: IShoppingMallCustomer.ILogin;
}): Promise<IShoppingMallCustomer.IAuthorized> {
  const customer = await MyGlobal.prisma.shopping_mall_customers.findFirst({
    where: { email: props.body.email },
    select: {
      ...ShoppingMallCustomerTransformer.select().select,
      password_hash: true,
    },
  });
  if (!customer) throw new HttpException("Invalid credentials", 401);
  const isValid = await PasswordUtil.verify(
    props.body.password,
    customer.password_hash,
  );
  if (!isValid) throw new HttpException("Invalid credentials", 401);
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
  const session = await MyGlobal.prisma.shopping_mall_customer_sessions.create({
    data: {
      id: v4(),
      shopping_mall_customer_id: customer.id,
      access_token: v4(),
      refresh_token: v4(),
      created_at: toISOStringSafe(new Date()),
      expired_at: toISOStringSafe(accessExpires),
      ip: props.ip ?? "0.0.0.0",
      referrer: props.body.referrer ?? "",
      user_agent: "",
    },
  });
  const token = {
    access: jwt.sign(
      {
        type: "customer",
        id: customer.id,
        session_id: session.id,
        created_at: toISOStringSafe(new Date()),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "1h", issuer: "autobe" },
    ),
    refresh: jwt.sign(
      {
        type: "customer",
        id: customer.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: toISOStringSafe(new Date()),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "7d", issuer: "autobe" },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };
  return {
    ...(await ShoppingMallCustomerTransformer.transform(customer)),
    customer: await ShoppingMallCustomerTransformer.transform(customer),
    token: {
      access: token.access,
      refresh: token.refresh,
      expired_at: token.expired_at,
      refreshable_until: token.refreshable_until,
    },
    tokens: {
      access_token: session.access_token,
      refresh_token: session.refresh_token,
      access_token_expires_at: toISOStringSafe(session.expired_at),
      refresh_token_expires_at: toISOStringSafe(refreshExpires),
      ip: session.ip,
      user_agent: session.user_agent ?? null,
      referrer: session.referrer ?? null,
      created_at: toISOStringSafe(session.created_at),
      updated_at: toISOStringSafe(new Date()),
    },
  } satisfies IShoppingMallCustomer.IAuthorized;
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
