  const data = await MyGlobal.prisma.shopping_mall_sellers.findMany({
    where,
    skip,
    take: limit,
    orderBy,
    select: {
      id: true,
      shop_name: true,
      shop_description: true,
      logo_image_url: true,
      approval_status: true,
      created_at: true,
