}): Promise<void> {
  const review = await MyGlobal.prisma.shopping_mall_reviews.findUniqueOrThrow({
    where: { id: props.reviewId },
    select: {
      id: true,
      shopping_mall_customer_id: true,
      shopping_mall_product_id: true,
      rating: true,
      text_content: true,
      is_deleted: true,
      deleted_at: true,
