import { TypedBody, TypedRoute } from "@nestia/core";
import { Controller, Ip } from "@nestjs/common";
import typia from "typia";

import { IShoppingMallSeller } from "../../../../api/structures/IShoppingMallSeller";
import { postShoppingMallAuthSellerJoin } from "../../../../providers/postShoppingMallAuthSellerJoin";
import { postShoppingMallAuthSellerLogin } from "../../../../providers/postShoppingMallAuthSellerLogin";
import { postShoppingMallAuthSellerRefresh } from "../../../../providers/postShoppingMallAuthSellerRefresh";

@Controller("/shoppingMall/auth/seller")
export class ShoppingmallAuthSellerController {
  /**
   * Seller registration endpoint for new business users to create accounts on the shopping mall platform.
   *
   * This API operation allows business users to register as sellers and begin the seller onboarding process. Upon successful registration, the seller account is created in 'pending' approval status, and the user receives temporary credentials for initial authentication.
   *
   * ## Business Context
   *
   * Sellers represent business entities that want to list products and manage their own shops on the platform. The registration process captures essential business information including shop name, description, and logo. All new sellers start with 'pending' approval status and must wait for administrator approval before gaining full seller privileges.
   *
   * ## Security Considerations
   *
   * The registration process validates email uniqueness, enforces password strength requirements, and creates initial session tokens for immediate temporary access. The registration triggers email verification and creates a seller record linked to the customer account.
   *
   * ## Database Integration
   *
   * This operation creates records in multiple tables:
   * - shopping_mall_customers: Customer account with kind='seller'
   * - shopping_mall_sellers: Seller-specific information with approval_status='pending'
   * - shopping_mall_seller_sessions: Initial authentication session
   * - shopping_mall_seller_email_verifications: Email verification token
   *
   * ## Related Operations
   *
   * - Login: Used after registration to obtain permanent credentials
   * - Refresh: Used to renew access tokens without re-authentication
   * - Profile Update: Used after approval to configure shop settings
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Seller registration information including email, password, and shop details.
   * @x-autobe-authorization-type join
   * @x-autobe-authorization-actor seller
   * @x-autobe-specification Seller registration flow: 1) Validate email uniqueness and password strength, 2) Create customer record with kind='seller', 3) Create seller record with approval_status='pending' and provided shop information, 4) Generate initial session tokens, 5) Create email verification token, 6) Send verification email, 7) Return authorized response with tokens and seller details. All operations wrapped in transaction for atomicity.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("join")
  public async join(
    @Ip()
    ip: string,
    @TypedBody()
    body: IShoppingMallSeller.IJoin,
  ): Promise<IShoppingMallSeller.IAuthorized> {
    try {
      return await postShoppingMallAuthSellerJoin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Seller login endpoint for authenticated access to seller dashboard and shop management features.
   *
   * This API operation allows registered sellers to authenticate using their email and password credentials. Upon successful validation, the system issues JWT access and refresh tokens for secure API access.
   *
   * ## Business Context
   *
   * Sellers use this endpoint to access their shop management dashboard, product management tools, order processing interfaces, and analytics dashboards. The login process validates credentials and establishes an authenticated session with appropriate permissions for seller operations.
   *
   * ## Security Considerations
   *
   * The login operation implements rate limiting to prevent brute force attacks, validates credentials against the database, checks seller approval status (must be 'approved' to login), and creates a new session record for token tracking. Failed login attempts are logged for security auditing.
   *
   * ## Database Integration
   *
   * This operation queries and updates multiple tables:
   * - shopping_mall_customers: Validates email and password credentials
   * - shopping_mall_sellers: Verifies approval_status='approved'
   * - shopping_mall_seller_sessions: Creates new session record with access/refresh tokens
   * - shopping_mall_seller_access_logs: Logs authentication event with IP and device info
   *
   * ## Related Operations
   *
   * - Join: Registration endpoint for new sellers
   * - Refresh: Used to renew access tokens when they expire
   * - Profile View: Accessible only after successful login
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Seller login credentials including email and password.
   * @x-autobe-authorization-type login
   * @x-autobe-authorization-actor seller
   * @x-autobe-specification Seller login flow: 1) Validate email exists and password matches (using bcrypt), 2) Verify seller record exists with approval_status='approved', 3) Create new session record with fresh access and refresh tokens, 4) Log authentication event for security audit, 5) Return authorized response with tokens and seller profile. Implement rate limiting and account lockout after failed attempts.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("login")
  public async login(
    @Ip()
    ip: string,
    @TypedBody()
    body: IShoppingMallSeller.ILogin,
  ): Promise<IShoppingMallSeller.IAuthorized> {
    try {
      return await postShoppingMallAuthSellerLogin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Token refresh endpoint for obtaining new access and refresh tokens without re-authentication.
   *
   * This API operation allows authenticated sellers to refresh their JWT tokens when the access token expires but the refresh token is still valid. This enables continuous session management without requiring users to log in again.
   *
   * ## Business Context
   *
   * Sellers benefit from seamless session management during extended use of the platform. The refresh token mechanism provides security through token rotation while maintaining user experience continuity. Sellers can maintain their session across page refreshes and长时间使用平台 without frequent re-authentication.
   *
   * ## Security Considerations
   *
   * The refresh operation implements token rotation (invalidating old tokens and issuing new ones), validates refresh token expiration, checks seller account status, and updates session records. This approach provides forward secrecy and limits the impact of token compromise.
   *
   * ## Database Integration
   *
   * This operation updates session tracking tables:
   * - shopping_mall_seller_sessions: Updates session with new tokens and validates refresh token
   * - shopping_mall_seller_access_logs: Logs token refresh event for security monitoring
   *
   * ## Related Operations
   *
   * - Login: Initial authentication that creates session with refresh token
   * - Join: Creates initial session after registration
   * - Logout (client-side): Client discards tokens (no server endpoint needed)
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Refresh token for obtaining new authentication tokens.
   * @x-autobe-authorization-type refresh
   * @x-autobe-authorization-actor seller
   * @x-autobe-specification Token refresh flow: 1) Validate provided refresh token matches stored session, 2) Check refresh token expiration, 3) Verify seller account status, 4) Invalidate old tokens and generate fresh access and refresh tokens, 5) Update session record with new tokens, 6) Log refresh event for security audit, 7) Return new authorized response. Implement token rotation for forward secrecy.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("refresh")
  public async refresh(
    @TypedBody()
    body: IShoppingMallSeller.IRefresh,
  ): Promise<IShoppingMallSeller.IAuthorized> {
    try {
      return await postShoppingMallAuthSellerRefresh({
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

