import { TypedBody, TypedParam, TypedRoute } from "@nestia/core";
import { Controller } from "@nestjs/common";
import typia from "typia";

import { IShoppingMallAdmin } from "../../../../api/structures/IShoppingMallAdmin";
import { AdminAuth } from "../../../../decorators/AdminAuth";
import { AdminPayload } from "../../../../decorators/payload/AdminPayload";
import { getShoppingMallAdminAdministratorsAdministratorId } from "../../../../providers/getShoppingMallAdminAdministratorsAdministratorId";
import { patchShoppingMallAdminAdministrators } from "../../../../providers/patchShoppingMallAdminAdministrators";
import { putShoppingMallAdminAdministratorsAdminIdDemote } from "../../../../providers/putShoppingMallAdminAdministratorsAdminIdDemote";
import { putShoppingMallAdminAdministratorsAdminIdPromote } from "../../../../providers/putShoppingMallAdminAdministratorsAdminIdPromote";

@Controller("/shoppingMall/admin/administrators")
export class ShoppingmallAdminAdministratorsController {
  /**
   * Submit an administrator promotion request.
   *
   * This operation allows authenticated users (customers or sellers) to formally request administrator privileges on the platform. Users must provide a written reason explaining why they should be granted administrator access.
   *
   * ## Administrator Request Workflow
   *
   * 1. User submits administrator request with written reason
   * 2. Super administrators can view all pending administrator requests
   * 3. Super administrators can approve or reject administrator applications
   * 4. Approved users gain administrator privileges
   * 5. Rejected users can submit new requests after receiving feedback
   *
   * ## Security Considerations
   *
   * - Only authenticated customers and sellers can submit administrator requests
   * - Requests are stored permanently for audit trail
   * - Rejection reasons are logged for transparency
   * - Administrator promotion is a privileged operation requiring super administrator approval
   *
   * ## Related Operations
   *
   * - `GET /admin/admin-requests` - List all administrator promotion requests (super admin only)
   * - `PUT /admin/admin-requests/:requestId/approve` - Approve administrator request (super admin only)
   * - `PUT /admin/admin-requests/:requestId/reject` - Reject administrator request (super admin only)
   *
   * ## Business Rules
   *
   * - Each user can have only one pending administrator request at a time
   * - Users can submit new requests after previous requests are rejected
   * - Administrator requests are preserved in the system for audit purposes
   *
   * @param connection
   * @param body Administrator promotion request data with reason
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor admin
   * @x-autobe-specification Handle administrator promotion request submission.
   * 1. Validate authenticated user (customer or seller)
   * 2. Parse request body for reason field
   * 3. Create administrator request record with user reference
   * 4. Set status to 'pending'
   * 5. Record creation timestamp
   * 6. Return request details with ID
   * 7. Log audit trail for compliance
   * 8. Return success response with created request data
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async requestAdministrator(
    @AdminAuth()
    admin: AdminPayload,
    @TypedBody()
    body: IShoppingMallAdmin.ICreate,
  ): Promise<IShoppingMallAdmin> {
    try {
      return await patchShoppingMallAdminAdministrators({
        admin,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve detailed information about a specific administrator account.
   *
   * This operation fetches the complete profile information for a single administrator by their unique identifier. The response includes all administrator account details including email, role grade, and timestamps.
   *
   * Administrators have elevated privileges in the system including the ability to manage seller accounts, approve registrations, oversee orders, and manage user accounts. This endpoint provides access to administrator account information for system oversight purposes.
   *
   * The operation validates that the requesting user has appropriate administrative privileges before returning administrator details.
   *
   * @param connection
   * @param administratorId Target administrator's unique identifier
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor admin
   * @x-autobe-specification Query the shopping_mall_admins table by id (UUID) to retrieve administrator account details. Return the administrator record including email, role_grade, created_at, updated_at, and deleted_at fields. Implement authorization check to ensure only administrators can access this endpoint.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get(":administratorId")
  public async at(
    @AdminAuth()
    admin: AdminPayload,
    @TypedParam("administratorId")
    administratorId: string,
  ): Promise<IShoppingMallAdmin> {
    try {
      return await getShoppingMallAdminAdministratorsAdministratorId({
        admin,
        administratorId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Promote a regular administrator to super administrator role.
   *
   * This operation allows super administrators to elevate a regular administrator's privileges to the highest level of system oversight. The promotion grants the administrator complete system management capabilities including the ability to manage other administrators.
   *
   * ## Authorization Requirements
   *
   * - Only super administrators can perform this operation
   * - The requesting administrator must have super administrator role grade
   * - Regular administrators cannot promote other administrators
   *
   * ## Business Logic
   *
   * - The administrator being promoted must currently have regular administrator role grade
   * - Super administrators cannot promote themselves (self-protection rule enforced)
   * - The promotion creates a role grade change record in the system for audit purposes
   *
   * ## Related Operations
   *
   * - GET /administrators/{adminId} - Retrieve administrator details
   * - PUT /administrators/{adminId}/demote - Demote super administrator to regular grade
   * - GET /admin/admin-requests - List administrator promotion requests (alternative workflow)
   *
   * @param connection
   * @param adminId The unique identifier of the administrator to promote
   * @param body Reason for administrator promotion
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor admin
   * @x-autobe-specification Update the role_grade field of the specified administrator from 'regular' to 'super'.
   *
   * 1. Validate that the requesting user is authenticated and has super administrator role
   * 2. Retrieve the administrator record by adminId from shopping_mall_admins table
   * 3. Verify that the target administrator exists and is not the same as the requesting administrator
   * 4. Check that the target administrator currently has role_grade = 'regular'
   * 5. Update the role_grade to 'super' in the shopping_mall_admins table
   * 6. Create an audit log entry for the role promotion
   * 7. Return the updated administrator record
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Put(":adminId/promote")
  public async promote(
    @AdminAuth()
    admin: AdminPayload,
    @TypedParam("adminId")
    adminId: string,
    @TypedBody()
    body: IShoppingMallAdmin.IPromote,
  ): Promise<IShoppingMallAdmin> {
    try {
      return await putShoppingMallAdminAdministratorsAdminIdPromote({
        admin,
        adminId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Demote a super administrator to regular administrator grade.
   *
   * This operation permanently changes the administrator's role grade from 'super' to 'regular', removing their elevated privileges including the ability to manage other administrators. Super administrators have complete system oversight and user management capabilities, while regular administrators have standard administrative capabilities.
   *
   * Only super administrators can perform this operation. The demoted administrator retains all other administrator privileges but loses the ability to promote/demote other administrators.
   *
   * This operation cannot be used to demote the super administrator from themselves (self-protection rule is enforced at the business logic layer).
   *
   * Security Considerations:
   * - Authorization: Only super administrators can demote other administrators
   * - Audit Trail: All demotion actions are logged in the system audit logs
   * - Irreversible: The grade change is permanent until re-promoted by another super administrator
   *
   * @param connection
   * @param adminId Target administrator's unique identifier
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor admin
   * @x-autobe-specification Update the shopping_mall_admins table to change role_grade from 'super' to 'regular'.
   *
   * Implementation Steps:
   * 1. Validate that current user is a super administrator (authorization check)
   * 2. Validate that target admin exists and is currently a super administrator
   * 3. Validate that target admin is not attempting to demote themselves (self-protection)
   * 4. Update the role_grade field to 'regular'
   * 5. Create audit log entry for the demotion action
   * 6. Return updated admin record
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Put(":adminId/demote")
  public async demote(
    @AdminAuth()
    admin: AdminPayload,
    @TypedParam("adminId")
    adminId: string,
  ): Promise<void> {
    try {
      return await putShoppingMallAdminAdministratorsAdminIdDemote({
        admin,
        adminId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

